package io.xeros.solo;
import io.xeros.*;import io.xeros.content.minigames.warriors_guild.*;import io.xeros.content.combat.*;import io.xeros.model.entity.npc.*;import io.xeros.model.entity.player.*;import io.xeros.model.entity.player.save.PlayerSave;import io.xeros.model.items.*;import java.util.*;import java.lang.reflect.*;import java.util.function.IntUnaryOperator;
public final class WarriorsPlayableCheck {
 static void ok(boolean b,String s){BossesPlayableCheck.ok(b,s);}static Player actor(){Player p=BossRoutesCheck.actor();p.setLoginName("warriors64qa");p.setDisplayName("Warriors64qa");return p;}static void at(Player p,int x,int y,int h){BossRoutesCheck.at(p,x,y,h);p.teleTimer=0;}static void give(Player p,int id,int n){ok(p.getItems().addItem(id,n),"Fixture "+id);}static int count(Player p,int id){return p.getItems().getInventoryCount(id);}static void clear(Player p){io.xeros.model.cycleevent.CycleEventHandler.getSingleton().stopEvents(p.getWarriorsGuild());BossesPlayableCheck.clear(p);}static void pickup(Player p,int id){GroundItem item=Server.itemHandler.getOwnedGroundItem(p,id,p.heightLevel);ok(item!=null,"Missing ground drop "+id);Server.itemHandler.removeGroundItem(p,item,true);}
 static void armour()throws Exception{for(AnimatedArmour.Armour a:AnimatedArmour.Armour.values()){Player p=actor();int x=a.ordinal()%2==0?2851:2857;at(p,x,3537,0);give(p,a.getHelmId(),1);give(p,a.getPlatebodyId(),1);give(p,a.getPlatelegsId(),1);AnimatedArmour.itemOnAnimator(p,a.getHelmId());ok(p.animatedArmourEscrow==a.getNpcId()&&count(p,a.getHelmId())==0,"Armour not reserved");AnimatedArmour.itemOnAnimator(p,a.getHelmId());SkillsAuditCheck.tick(6);NPC n=BarrowsPlayableCheck.owned(p,a.getNpcId());ok(n.makeX==x&&n.getHealth().getCurrentHealth()==a.getHealth(),"Wrong animator/health");BarrowsPlayableCheck.death(p,n);pickup(p,8851);pickup(p,a.getHelmId());pickup(p,a.getPlatebodyId());pickup(p,a.getPlatelegsId());ok(count(p,8851)==a.getAmountOfTokens()&&count(p,a.getHelmId())==1&&p.animatedArmourEscrow==-1&&!p.isAnimatedArmourSpawned,"Armour/token return");n.unregisterInstant();clear(p);}System.out.println("WARRIORS_ALL_SIX_ARMOUR_SETS_BOTH_ANIMATORS_NATIVE_COMBAT_DEATH_TOKENS_AND_THREE_PIECE_RETURN_PASS");
 Player p=actor();at(p,2851,3537,0);give(p,1163,1);give(p,1127,1);give(p,1079,1);AnimatedArmour.itemOnAnimator(p,1163);ok(PlayerSave.saveGameInstant(p),"Escrow save");p.setDisconnected(true);SkillsAuditCheck.tick(8);Player q=actor();ok(PlayerSave.loadGame(q,"warriors64qa","IsolatedAudit",true).toString().equals("SUCCESS")&&q.animatedArmourEscrow==2456,"Escrow reload");AnimatedArmour.recover(q);AnimatedArmour.recover(q);ok(count(q,1163)==1&&count(q,1127)==1&&count(q,1079)==1&&q.animatedArmourEscrow==-1,"Escrow duplicated or lost");ok(PlayerSave.saveGameInstant(q),"Recovered save");Player v=actor();ok(PlayerSave.loadGame(v,"warriors64qa","IsolatedAudit",true).toString().equals("SUCCESS")&&v.animatedArmourEscrow==-1&&count(v,1163)==1,"Recovery save reload");clear(p);clear(q);clear(v);System.out.println("WARRIORS_ANIMATOR_DISCONNECT_ESCROW_REAL_SAVE_RELOAD_RECOVERY_EXACTLY_ONCE_PASS");}
 static void defenders()throws Exception{Player p=actor();at(p,2846,3540,2);ok(!p.getWarriorsGuild().enter(),"Free token entry");give(p,8851,250);ok(p.getWarriorsGuild().enter(),"Guild door");BossesPlayableCheck.applied(p);p.teleTimer=0;Field f=WarriorsGuild.class.getDeclaredField("lootRoll");f.setAccessible(true);f.set(p.getWarriorsGuild(),(IntUnaryOperator)(b->0));for(int[] data:WarriorsGuild.DEFENDER_DATA){NPC n=NPCSpawning.spawnNpc(p,2463,2853,3540,2,0,10,false,false);BarrowsPlayableCheck.death(p,n);GroundItem drop=Server.itemHandler.getOwnedGroundItem(p,data[0],2);ok(drop!=null&&drop.getAmount()==1,"Missing defender "+data[0]);n.getHealth().setCurrentHealth(0);p.getWarriorsGuild().dropDefender(n);ok(drop.getAmount()==1,"Repeated defender death");pickup(p,data[0]);n.unregisterInstant();}
 ok(count(p,12954)==1,"Dragon progression");SkillsAuditCheck.tick(200);ok(count(p,8851)==230&&p.getWarriorsGuild().isActive(),"Token drain");ok(PlayerSave.saveGameInstant(p),"Defender save");Player q=actor();ok(PlayerSave.loadGame(q,"warriors64qa","IsolatedAudit",true).toString().equals("SUCCESS")&&count(q,12954)==1&&count(q,8851)==230,"Dragon/token persistence");PlayerHandler.players[1]=p;clear(q);p.getItems().deleteItem2(8851,215);p.getWarriorsGuild().cycle();SkillsAuditCheck.tick(200);ok(!p.getWarriorsGuild().isActive()&&p.getTeleportToX()==2846&&count(p,8851)==15,"Token exhaustion");clear(p);System.out.println("WARRIORS_REAL_DOOR_200_TOKEN_GATE_EIGHT_DEFENDERS_NATIVE_CYCLOPS_DEATH_SINGLE_DROP_20_TOKEN_DRAIN_EXHAUSTION_AND_SAVE_RELOAD_PASS");}
 static void guards()throws Exception{for(int mode=0;mode<4;mode++){Player p=actor();at(p,2851,3537,0);give(p,1163,1);give(p,1127,1);give(p,1079,1);if(mode==0)p.isDead=true;if(mode==1)p.isBanking=true;if(mode==2)p.teleTimer=2;if(mode==3)at(p,2853,3537,0);AnimatedArmour.itemOnAnimator(p,1163);ok(count(p,1163)==1&&p.animatedArmourEscrow==-1,"Animator guard "+mode);clear(p);}Player p=actor();at(p,2853,3540,2);give(p,8851,250);p.getWarriorsGuild().cycle();Field f=WarriorsGuild.class.getDeclaredField("lootRoll");f.setAccessible(true);f.set(p.getWarriorsGuild(),(IntUnaryOperator)(b->0));NPC chicken=NPCSpawning.spawnNpc(p,2805,2853,3540,2,0,0,false,false);BarrowsPlayableCheck.death(p,chicken);ok(Server.itemHandler.getOwnedGroundItem(p,8844,2)==null,"Non-cyclops dropped defender");chicken.unregisterInstant();at(p,3101,3509,0);SkillsAuditCheck.tick(200);ok(!p.getWarriorsGuild().isActive()&&count(p,8851)==250,"Outside room token drain");clear(p);p=actor();at(p,2853,3540,2);give(p,8851,250);ok(p.getInventory().addToBank(new ImmutableItem(8850,1)),"Bank rune defender fixture");p.getWarriorsGuild().cycle();f.set(p.getWarriorsGuild(),(IntUnaryOperator)(b->0));NPC cyclops=NPCSpawning.spawnNpc(p,2463,2853,3540,2,0,10,false,false);BarrowsPlayableCheck.death(p,cyclops);ok(Server.itemHandler.getOwnedGroundItem(p,12954,2)!=null,"Banked rune defender not recognised");cyclops.unregisterInstant();clear(p);System.out.println("WARRIORS_ANIMATOR_DEAD_BANK_TELEPORT_POSITION_GUARDS_NO_NON_CYCLOPS_DEFENDER_BANKED_RUNE_PROGRESSION_AND_EXIT_CANCEL_PASS");}
 public static void main(String[]a)throws Exception{Thread.setDefaultUncaughtExceptionHandler((t,e)->{e.printStackTrace();System.exit(1);});Thread.currentThread().setName("GameThread");System.setProperty("solo.mode","true");System.setProperty("solo.xp","1");Server.startServerless();Configuration.BONUS_SKILL=-1;armour();defenders();guards();System.out.println("WARRIORS_DEFENDERS_PLAYABLE_V64_PASS");System.exit(0);}
}
